import { GraphQLClient, RequestOptions } from 'graphql-request';
import gql from 'graphql-tag';
export type Maybe<T> = T | null;
export type InputMaybe<T> = Maybe<T>;
export type Exact<T extends { [key: string]: unknown }> = { [K in keyof T]: T[K] };
export type MakeOptional<T, K extends keyof T> = Omit<T, K> & { [SubKey in K]?: Maybe<T[SubKey]> };
export type MakeMaybe<T, K extends keyof T> = Omit<T, K> & { [SubKey in K]: Maybe<T[SubKey]> };
export type MakeEmpty<T extends { [key: string]: unknown }, K extends keyof T> = { [_ in K]?: never };
export type Incremental<T> = T | { [P in keyof T]?: P extends ' $fragmentName' | '__typename' ? T[P] : never };
type GraphQLClientRequestHeaders = RequestOptions['requestHeaders'];
/** All built-in and custom scalars, mapped to their actual values */
export type Scalars = {
  ID: { input: string; output: string; }
  String: { input: string; output: string; }
  Boolean: { input: boolean; output: boolean; }
  Int: { input: number; output: number; }
  Float: { input: number; output: number; }
  /** The `Any` scalar any type */
  Any: { input: any; output: any; }
  /** The `ArrayLike` scalar type represents a reference to a store previously created by the user n a datalayer */
  ArrayLike: { input: any; output: any; }
  /** Date with time (isoformat) */
  DateTime: { input: any; output: any; }
  /** A reference to an uploaded **fabriks store**: one prefix holding `fabriks.json`, both catalogs and every octree level. Request it with `requestFabriksUpload`, write the tree, land the manifest last, then `finishFabriksUpload` -- which reads the manifest and refuses a prefix without one. A collection registered this way declares no grid and no encoding: the server reads them from the artifact, so they cannot be stated wrong */
  FabriksLike: { input: any; output: any; }
  /** The `FileLike` scalar type represents a reference to a big file storage previously created by the user n a datalayer */
  FileLike: { input: any; output: any; }
  /** A quantity of frequency (``"50 Hz"``, ``"1 kHz"``). */
  Frequency: { input: any; output: any; }
  /**
   * A physical quantity of any dimension (``"0.12 S/cm2"``, ``"-54.3 mV"``, ``"2 mM"``).
   *
   * Unlike the dimension-locked scalars, this keeps whatever unit the value
   * carries and does not normalize to a canonical integer — its dimension is
   * whatever the value has. A bare number without a unit is rejected. On the wire
   * it is a string; validating it against an expected dimension (e.g. a declared
   * mechanism parameter) is the caller's job.
   */
  GenericQuantity: { input: any; output: any; }
  /** The `ImageFileLike` scalar type represents a reference to a snapshot image previously created by the user n a datalayer */
  ImageFileLike: { input: any; output: any; }
  /** The `JSON` scalar type represents JSON values as specified by [ECMA-404](https://ecma-international.org/wp-content/uploads/ECMA-404_2nd_edition_december_2017.pdf). */
  JSON: { input: any; output: any; }
  /** A reference to an uploaded **konnektion store**: one prefix holding `konnektion.json`, both catalogs and every octree level of a node/edge network. Named for the wire format the way `FabriksLike` is, and a separate scalar because it is a separate format -- a graph, not a surface. Request it with `requestKonnektionUpload`, write the tree, land the manifest last, then `finishKonnektionUpload` -- which reads the manifest and refuses a prefix without one. A collection registered this way declares no grid and no encoding: the server reads them from the artifact, so they cannot be stated wrong */
  KonnektionLike: { input: any; output: any; }
  /** A spatial length (``"2.5 µm"``, ``"1 mm"``, ``"3 m"``). */
  Length: { input: any; output: any; }
  /** The `ParquetLike` scalar type represents a reference to a parquet objected stored previously created by the user on a datalayer */
  ParquetLike: { input: any; output: any; }
  /** A power (``"5 mW"``, ``"2 W"``). */
  Power: { input: any; output: any; }
  /** A reference to an uploaded **sporadik store**: one prefix holding one child per axis made contiguous, under `layouts/axis{k}`, each an anndata-spelled sparse group of `data`, `indices` and `indptr`. Named for the wire format the way `FabriksLike` is. Request it with `requestSparseUpload`, write the layouts, land the `sporadik` block last, then `finishSparseUpload` -- which reads that block and refuses a prefix without one, because zarr fills a missing chunk rather than failing and a torn upload is otherwise indistinguishable from a finished one. A dataset registered this way declares no encoding, no shape and no chunking: the server reads them from the artifact, so they cannot be stated wrong */
  SporadikLike: { input: any; output: any; }
  /** A temperature (``"310 K"``, ``"37 degC"``). */
  Temperature: { input: any; output: any; }
  /** The `Vector` scalar type represents a matrix values as specified by */
  ThreeDVector: { input: any; output: any; }
  UUID: { input: any; output: any; }
  /**
   * A physical unit of measurement (``"mV"``, ``"S/cm2"``, ``"second"``).
   *
   * A string scalar validating that the value parses as a pint unit — a bad unit,
   * a bare quantity (``"5 mV"``), or a dimension is rejected. Compact exponent
   * spelling (``"cm2"``) is accepted and the given spelling is preserved.
   */
  Unit: { input: any; output: any; }
  _Any: { input: any; output: any; }
};

/** A whole placement path composed into one affine map, labelled with the axes it is written over. `matrix` is M x (N+1) with rows outermost -- the same layout an AffineTransformation's `affine` uses -- its columns in `inputAxes` order and its last column the translation. **`outputAxes` names only the destination axes the path actually constrains**: a (c,y,x) dataset registered on (y,x) into a (t,z,y,x) world gets two rows, not four, because the registration says nothing about t and z and a zero row there would pin the data at their origin rather than leave it unstated. `total` is whether the map covers every destination axis */
export type AffinePlacement = {
  __typename?: 'AffinePlacement';
  /** The axes the matrix's columns are in, which is the layer's own source coordinate system's axis order */
  inputAxes: Array<Scalars['String']['output']>;
  /** The composed map, M x (N+1), rows outermost. One row per axis in `outputAxes`, one column per axis in `inputAxes`, plus a final translation column */
  matrix: Array<Array<Scalars['Float']['output']>>;
  /** The destination axes the matrix's rows are in, in the world's own axis order. An axis the path says nothing about has no row at all */
  outputAxes: Array<Scalars['String']['output']>;
  /** Whether `outputAxes` covers every axis of the destination space. False for a partial registration -- an honest map over the axes it names, and silence about the rest */
  total: Scalars['Boolean']['output'];
};

/** The fields an AFFINE member of TransformInput reads. Published for codegen; the wire type is the flat TransformInput */
export type AffineTransformInput = {
  affine: Array<Array<Scalars['Float']['input']>>;
  kind?: CreatableTransformKind;
};

/** A general affine map, given as an M x (N+1) matrix with rows outermost */
export type AffineTransformation = Transformation & {
  __typename?: 'AffineTransformation';
  /** The affine matrix, M x (N+1), rows outermost. The last column is the translation */
  affine: Array<Array<Scalars['Float']['output']>>;
  createdAt: Scalars['DateTime']['output'];
  creator?: Maybe<User>;
  id: Scalars['ID']['output'];
  input?: Maybe<CoordinateSystem>;
  /** The names of the input axes this edge's parameters are ordered by. `scale`, `translation` and the columns of `affine` follow this order -- which is the input system's axis order, NOT the reading layer's axis names, and the two differ often enough that indexing the arrays against them silently misplaces them. A BY_DIMENSION edge names only the subset of axes it acts on; the axes it does not name are the ones it leaves untouched */
  inputAxes: Array<Scalars['String']['output']>;
  /** Which geometric properties survive this edge's map, derived from `kind`: ISOMETRY (distances, angles and areas all transfer), SIMILARITY (angles and length ratios transfer, absolute lengths scale by one common factor), AFFINE (parallelism and area ratios transfer, angles and distances do not), DIFFEOMORPHIC (topology at best, and only locally -- the Jacobian varies with position), NONE (nothing corresponds). A SEQUENCE or BY_DIMENSION is the weakest of its children. Stated by kind, never by inspecting the numbers: an AFFINE edge reads AFFINE even when its matrix happens to be rigid, because separating those needs an SVD. A layer's `placementInvariance` is the minimum of this over its whole path to world */
  invariance: TransformInvariance;
  kind: TransformKind;
  name?: Maybe<Scalars['String']['output']>;
  output?: Maybe<CoordinateSystem>;
  /** The names of the output axes this edge produces. For a rank-changing BY_DIMENSION edge (placing a (c,y,x) dataset into a (t,z,y,x) world) this is the subset it maps onto; the world's other axes are untouched */
  outputAxes: Array<Scalars['String']['output']>;
  /** Provenance entries for this edge: who authored it, and every refinement since. A refinement rewrites the edge in place, so this audit trail is where the placement's earlier states live -- and counting these rows along a chain is what `CoordinateSystem.transformVersion` reports */
  provenanceEntries: Array<ProvenanceEntry>;
  /** Where along one axis this edge applies, or null for an edge that holds everywhere -- which is almost every edge. A per-channel correction is scoped to {axis: "c", index: 2}; several such edges over one axis are one piecewise map. A path query crosses a scoped edge only when it fixes that coordinate with `at` */
  selector?: Maybe<Selector>;
  /** How much this map is actually known: VALIDATED for a map the server derived (or one someone checked), INFERRED for numbers read from metadata, MANUAL for an authored registration, UNKNOWN for one its author marked as a guess. A layer's validity is the weakest edge on its path to world */
  validity: PlacementValidity;
  /** (derivation edges) What the operation this edge records did to the *values*, orthogonal to `kind`: IDENTICAL (a crop -- statistics transfer), TRANSFORMED (a deconvolution -- same quantity, new numbers), CATEGORIZED (a threshold -- values became labels, and a bootstrapped scene renders the data as a label map). Null when unstated, and never present on a registration -- values do not cross a claim between spaces */
  valueRelation?: Maybe<ValueRelation>;
  /** How many times this edge has been written, counting the row that created it -- so a new edge reads 1. Only comparison is meaningful: this and the edge's `id` together are the cache key for anything derived from the edge, and a change means refetch. It counts the same provenance rows `provenanceEntries` lists, so the audit trail and the token cannot disagree; a rename moves it too, which errs towards refetching something that did not change rather than trusting something that did */
  version: Scalars['Int']['output'];
};


/** A general affine map, given as an M x (N+1) matrix with rows outermost */
export type AffineTransformationProvenanceEntriesArgs = {
  pagination?: InputMaybe<OffsetPaginationInput>;
};

/** A named camera tour of a scene: the poses a viewer pans through, in order. A view artifact -- it cascades with the scene, no placement walk crosses it, and refining a registration moves the data but never the camera */
export type Animation = {
  __typename?: 'Animation';
  createdAt: Scalars['DateTime']['output'];
  /** The task this tour was created through, if any */
  createdThrough?: Maybe<Task>;
  /** The assigner of the creating task, if any */
  createdThroughBy?: Maybe<User>;
  creator?: Maybe<User>;
  description?: Maybe<Scalars['String']['output']>;
  id: Scalars['ID']['output'];
  name: Scalars['String']['output'];
  /** The scene this tour flies through */
  scene: Scene;
  /** The poses the viewer pans through, in tour order */
  waypoints: Array<AnimationWaypoint>;
};


/** A named camera tour of a scene: the poses a viewer pans through, in order. A view artifact -- it cascades with the scene, no placement walk crosses it, and refining a registration moves the data but never the camera */
export type AnimationWaypointsArgs = {
  pagination?: InputMaybe<OffsetPaginationInput>;
};

export type AnimationFilter = {
  AND?: InputMaybe<AnimationFilter>;
  DISTINCT?: InputMaybe<Scalars['Boolean']['input']>;
  NOT?: InputMaybe<AnimationFilter>;
  OR?: InputMaybe<AnimationFilter>;
  /** Filter by the sub of the user that assigned the creating task */
  assignedBy?: InputMaybe<Scalars['ID']['input']>;
  /** Filter for items created after this datetime */
  createdAfter?: InputMaybe<Scalars['DateTime']['input']>;
  /** Filter for items created before this datetime */
  createdBefore?: InputMaybe<Scalars['DateTime']['input']>;
  /** Filter by the database ID of the task the item was created through (the `createdThrough { id }` field) */
  createdThrough?: InputMaybe<Scalars['ID']['input']>;
  /** Filter by the database ID of the user that assigned the creating task (the `createdThroughBy { id }` field) */
  createdThroughBy?: InputMaybe<Scalars['ID']['input']>;
  /** Filter by the rekuest task id the item was created through */
  createdThroughTask?: InputMaybe<Scalars['String']['input']>;
  id?: InputMaybe<Scalars['ID']['input']>;
  /** Filter by list of IDs */
  ids?: InputMaybe<Array<Scalars['ID']['input']>>;
  name?: InputMaybe<StrFilterLookup>;
  /** Filter by the creator's subject ID */
  owner?: InputMaybe<Scalars['ID']['input']>;
  /** Filter by the scene this tour flies through */
  scene?: InputMaybe<Scalars['ID']['input']>;
  /** Search by name (case-insensitive substring) */
  search?: InputMaybe<Scalars['String']['input']>;
};

export type AnimationOrder =
  { createdAt: Ordering; id?: never; name?: never; }
  |  { createdAt?: never; id: Ordering; name?: never; }
  |  { createdAt?: never; id?: never; name: Ordering; };

/** One camera pose in a tour, and how the viewer travels to it */
export type AnimationWaypoint = {
  __typename?: 'AnimationWaypoint';
  /** The tour this pose belongs to */
  animation: Animation;
  /** Where the camera is: a position keyed by the world's axis names, plus the flat and volumetric views of it */
  camera: CameraState;
  /** How long the viewer takes to travel TO this pose, in milliseconds. Ignored for the first pose, which is where the tour starts */
  durationMs: Scalars['Int']['output'];
  /** How the viewer eases the camera along that travel */
  easing: Easing;
  id: Scalars['ID']['output'];
  /** What this stop shows, e.g. 'the nucleus' */
  name: Scalars['String']['output'];
  /** The pose's index in the tour. Written by enumeration when the tour is authored, so it always runs 0, 1, 2 ... with no gaps */
  order: Scalars['Int']['output'];
};

/** One camera pose in a tour, and how the viewer travels to it. Its position in the tour is its position in the `waypoints` list -- there is no order field to pass */
export type AnimationWaypointInput = {
  /** Where the camera is at this stop */
  camera: CameraStateInput;
  /** How long the viewer takes to travel to this stop, in milliseconds */
  durationMs?: InputMaybe<Scalars['Int']['input']>;
  /** How the viewer eases the camera along that travel */
  easing?: InputMaybe<Easing>;
  /** What this stop shows */
  name?: InputMaybe<Scalars['String']['input']>;
};

/** A human-drawn shape in an annotation collection's coordinate system. It belongs to the collection, not to a scene: delete the scene and the annotation survives */
export type Annotation = {
  __typename?: 'Annotation';
  /** The collection this annotation belongs to; its vectors are expressed in the collection's own coordinate system */
  collection: AnnotationCollection;
  /** The coordinate system this annotation's vectors are expressed in: its collection's own system */
  coordinateSystem?: Maybe<CoordinateSystem>;
  /** The discrete coordinates this annotation is pinned to. A coordinate the annotation does not pin is one it spans */
  coordinates: Array<Coordinate>;
  createdWithTransforms: Scalars['Int']['output'];
  description?: Maybe<Scalars['String']['output']>;
  /** The fill color of the geometry, as RGBA, or null for no fill */
  fillColor?: Maybe<Array<Scalars['Int']['output']>>;
  /** Whether the geometry is filled with fill_color */
  filled: Scalars['Boolean']['output'];
  id: Scalars['UUID']['output'];
  /** The annotation's bounding box in the nearest intrinsic space its collection's chain reaches, derived from every corner of its geometry (an affine-transformed box is not a box: min/max alone gives a strictly too-small answer under rotation or shear). Intrinsic, not world: world is scene-owned, and one collection can sit in two scenes under two registrations. **Not always a dataset's pixel grid**: a registration, or a derivation that changes rank, is not something a box can be pushed across -- it says nothing about the axes it does not name, so there is no extent to give them -- and the box then stays in the collection's own drawing space. Boxes compare only within one frame, which is why the spatial filters require a collection or coordinate system alongside */
  intrinsicBbox?: Maybe<BoundingBox>;
  kind: AnnotationKind;
  name: Scalars['String']['output'];
  /** Provenance entries for this annotation */
  provenanceEntries: Array<ProvenanceEntry>;
  /** The stroke (outline) color of the geometry, as RGBA */
  strokeColor?: Maybe<Array<Scalars['Int']['output']>>;
  /** The stroke width of the geometry, in the drawing space's units. One number for every direction, so it is a well-defined length only where that space's axes share a scale */
  strokeWidth: Scalars['Float']['output'];
  vectors: Array<Array<Scalars['Float']['output']>>;
};


/** A human-drawn shape in an annotation collection's coordinate system. It belongs to the collection, not to a scene: delete the scene and the annotation survives */
export type AnnotationProvenanceEntriesArgs = {
  pagination?: InputMaybe<OffsetPaginationInput>;
};

/** A named set of human-drawn annotations, owning the coordinate system they are drawn in. The CRUD counterpart of a table dataset's machine-produced rows: shapes a person draws and edits, sharing one drawing space and one registration story */
export type AnnotationCollection = {
  __typename?: 'AnnotationCollection';
  /** The annotations in this collection */
  annotations: Array<Annotation>;
  /** The coordinate system the annotations' vectors are expressed in. The collection owns it; `derivedFrom` relates it to whatever the shapes are drawn over */
  coordinateSystem: CoordinateSystem;
  createdAt: Scalars['DateTime']['output'];
  creator?: Maybe<User>;
  /** Every edge from this collection's space back into data the shapes are drawn over, in declared order -- the first is the primary parent, the one that places it. An identity into a scene's world for a scene-minted collection, an identity into a dataset's system for one drawn over an image. Empty for a freestanding collection */
  derivedFrom: Array<Transformation>;
  description?: Maybe<Scalars['String']['output']>;
  /** The files written out of this annotation collection: an OME-TIFF export, a rendered snapshot registered as a file. The mirror of `sourceFiles` */
  exports: Array<FileLink>;
  /** The folder this annotation collection is filed in. Organisational only: distinct from `scene`, which says which drawing surface minted it, and from `coordinateSystem`, which says where its shapes are drawn */
  folder?: Maybe<Folder>;
  id: Scalars['ID']['output'];
  name: Scalars['String']['output'];
  /** Provenance entries for this annotation collection */
  provenanceEntries: Array<ProvenanceEntry>;
  /** The scene this collection was minted for as its default drawing surface, or null for a freestanding or dataset-derived collection. Bookkeeping, not placement: the registration edge is what places it */
  scene?: Maybe<Scene>;
  /** The files this annotation collection was converted from -- the CZI a converter read to write these arrays, named per series. **Read this alongside `derivedFrom`, not instead of it**: `derivedFrom` says which *data* this was computed from and relates two coordinate systems, while this says which *bytes* it was read out of and relates to no space at all, because a file has none. Both can be non-empty and complete */
  sourceFiles: Array<FileLink>;
};


/** A named set of human-drawn annotations, owning the coordinate system they are drawn in. The CRUD counterpart of a table dataset's machine-produced rows: shapes a person draws and edits, sharing one drawing space and one registration story */
export type AnnotationCollectionAnnotationsArgs = {
  filters?: InputMaybe<AnnotationFilter>;
  ordering?: Array<AnnotationOrder>;
  pagination?: InputMaybe<OffsetPaginationInput>;
};


/** A named set of human-drawn annotations, owning the coordinate system they are drawn in. The CRUD counterpart of a table dataset's machine-produced rows: shapes a person draws and edits, sharing one drawing space and one registration story */
export type AnnotationCollectionExportsArgs = {
  filters?: InputMaybe<FileLinkFilter>;
};


/** A named set of human-drawn annotations, owning the coordinate system they are drawn in. The CRUD counterpart of a table dataset's machine-produced rows: shapes a person draws and edits, sharing one drawing space and one registration story */
export type AnnotationCollectionProvenanceEntriesArgs = {
  pagination?: InputMaybe<OffsetPaginationInput>;
};


/** A named set of human-drawn annotations, owning the coordinate system they are drawn in. The CRUD counterpart of a table dataset's machine-produced rows: shapes a person draws and edits, sharing one drawing space and one registration story */
export type AnnotationCollectionSourceFilesArgs = {
  filters?: InputMaybe<FileLinkFilter>;
};

/** The fields an ANNOTATION_COLLECTION derivation reads. Published for codegen; the wire type is the flat DerivedFromInput */
export type AnnotationCollectionDerivedFromInput = {
  annotationCollection: Scalars['ID']['input'];
  kind?: DerivationSourceKind;
  transform?: InputMaybe<TransformInput>;
  valueRelation?: InputMaybe<ValueRelation>;
};

/** The fields an ANNOTATION_COLLECTION export link reads. Published for codegen; the wire type is the flat ExportOfInput */
export type AnnotationCollectionExportOfInput = {
  annotationCollection: Scalars['ID']['input'];
  kind?: FileLinkContainerKind;
  seriesIdentifier?: InputMaybe<Scalars['String']['input']>;
  valueRelation?: InputMaybe<ValueRelation>;
};

export type AnnotationCollectionFilter = {
  AND?: InputMaybe<AnnotationCollectionFilter>;
  DISTINCT?: InputMaybe<Scalars['Boolean']['input']>;
  NOT?: InputMaybe<AnnotationCollectionFilter>;
  OR?: InputMaybe<AnnotationCollectionFilter>;
  /** Filter by the coordinate system the annotations are drawn in (the collection's own) */
  coordinateSystem?: InputMaybe<Scalars['ID']['input']>;
  /** Filter for items created after this datetime */
  createdAfter?: InputMaybe<Scalars['DateTime']['input']>;
  /** Filter for items created before this datetime */
  createdBefore?: InputMaybe<Scalars['DateTime']['input']>;
  /** Filter by the dataset the shapes are drawn over, following the derivation edge */
  dataset?: InputMaybe<Scalars['ID']['input']>;
  /** Filter by the folder this annotation collection is filed in */
  folder?: InputMaybe<Scalars['ID']['input']>;
  /** Filter by a list of folder IDs */
  folders?: InputMaybe<Array<Scalars['ID']['input']>>;
  id?: InputMaybe<Scalars['ID']['input']>;
  /** Filter by list of IDs */
  ids?: InputMaybe<Array<Scalars['ID']['input']>>;
  name?: InputMaybe<StrFilterLookup>;
  /** Filter by the creator's subject ID */
  owner?: InputMaybe<Scalars['ID']['input']>;
  /** Filter by the scene this collection was minted for as its default drawing surface */
  scene?: InputMaybe<Scalars['ID']['input']>;
  /** Search by name (case-insensitive substring) */
  search?: InputMaybe<Scalars['String']['input']>;
};

export type AnnotationCollectionOrder =
  { createdAt: Ordering; id?: never; name?: never; }
  |  { createdAt?: never; id: Ordering; name?: never; }
  |  { createdAt?: never; id?: never; name: Ordering; };

export type AnnotationFilter = {
  AND?: InputMaybe<AnnotationFilter>;
  DISTINCT?: InputMaybe<Scalars['Boolean']['input']>;
  NOT?: InputMaybe<AnnotationFilter>;
  OR?: InputMaybe<AnnotationFilter>;
  /** Filter by the collection this annotation belongs to */
  collection?: InputMaybe<Scalars['ID']['input']>;
  /** Filter to annotations whose intrinsic bounding box contains this point (GiST-backed). Only meaningful within one frame: pass `collection` or `coordinateSystem` alongside */
  containsPoint?: InputMaybe<Array<Scalars['Float']['input']>>;
  /** Filter by the coordinate system this annotation is drawn in (its collection's own) */
  coordinateSystem?: InputMaybe<Scalars['ID']['input']>;
  /** Filter by the dataset the annotations are drawn over, following the collection's derivation edge */
  dataset?: InputMaybe<Scalars['ID']['input']>;
  description?: InputMaybe<StrFilterLookup>;
  id?: InputMaybe<Scalars['UUID']['input']>;
  /** Filter by list of IDs */
  ids?: InputMaybe<Array<Scalars['ID']['input']>>;
  /** Filter to annotations whose intrinsic bounding box overlaps this box (GiST-backed). Only meaningful within one frame: pass `collection` or `coordinateSystem` alongside. A box of lower rank is zero-filled on the missing coordinates */
  intersects?: InputMaybe<BoundingBoxInput>;
  kind?: InputMaybe<AnnotationKindChoices>;
  name?: InputMaybe<StrFilterLookup>;
  /** Filter to annotations pinned to every one of these coordinates, e.g. [{name: 't', value: 3}]. GIN-backed containment on the stored coordinate dict; an annotation that spans a coordinate does not match a pin on it */
  pinnedTo?: InputMaybe<Array<CoordinateInput>>;
  /** Search by name (case-insensitive substring) */
  search?: InputMaybe<Scalars['String']['input']>;
};

/** The physical unit used to express spatial dimensions, e.g. of pixel sizes or stage positions. */
export enum AnnotationKind {
  /** A round shape across two axes with one radius. Vectors are the two opposite corners of its bounding box; the radius is half the (uniform by construction) extent. */
  Circle = 'CIRCLE',
  /** An axis-aligned box across three axes, stored as the two opposite corners of its bounding box. */
  Cube = 'CUBE',
  /** A round shape across two axes with a radius per axis. Vectors are the two opposite corners of its bounding box; each semi-axis is half that axis' extent. */
  Ellipse = 'ELLIPSE',
  /** A round shape across three axes with a radius per axis. Vectors are the two opposite corners of its bounding box; each semi-axis is half that axis' extent. */
  Ellipsoid = 'ELLIPSOID',
  /** A straight line between two points. */
  Line = 'LINE',
  /** A set of unconnected points drawn as one region, e.g. a counting click set. Vectors are the points themselves, in no particular order and with no connectivity implied. */
  MultiPoint = 'MULTI_POINT',
  /** An open path defined by a sequence of connected points. */
  Path = 'PATH',
  /** A single point. */
  Point = 'POINT',
  /** A closed polygon defined by a sequence of vertices. */
  Polygon = 'POLYGON',
  /** An axis-aligned box across two axes, stored as the two opposite corners of its bounding box. Which two axes it spans is read from the coordinate system, not from this kind. */
  Rectangle = 'RECTANGLE',
  /** A round shape across three axes with one radius. Vectors are the two opposite corners of its bounding box. */
  Sphere = 'SPHERE'
}

export enum AnnotationKindChoices {
  Circle = 'CIRCLE',
  Cube = 'CUBE',
  Ellipse = 'ELLIPSE',
  Ellipsoid = 'ELLIPSOID',
  Line = 'LINE',
  MultiPoint = 'MULTI_POINT',
  Path = 'PATH',
  Point = 'POINT',
  Polygon = 'POLYGON',
  Rectangle = 'RECTANGLE',
  Sphere = 'SPHERE'
}

/** A layer that renders an annotation collection's drawn shapes (polygons, boxes, ellipses, lines, paths) in a scene. One layer per collection: per-shape styling lives on the annotations themselves. */
export type AnnotationLayer = Layer & {
  __typename?: 'AnnotationLayer';
  /** The annotation collection whose shapes this layer renders. Its own coordinate system is the layer's space */
  annotationCollection: AnnotationCollection;
  /** This layer's whole `pathToWorld` composed into one affine map -- the same path, same edges, same order, with the flagged steps inverted. Derived on read and stored nowhere, exactly as the path itself is, so refining one registration moves it. **Null when `pathToWorld` is null** and for the same two reasons; `placement` is what tells them apart. It errors rather than returning null when a path exists but does not condense: a FIELD step gives its map as the values of an array and has no closed form, and a singular step cannot be walked backwards -- the error names the transformation that stopped it. Note that `placementInvariance` being AFFINE or stronger is necessary but not sufficient for this to succeed. `outputAxes` names only the destination axes the path constrains, so pass `strict: true` to be refused a partial map instead of handed one */
  asAffine?: Maybe<AffinePlacement>;
  blending: Blending;
  id: Scalars['ID']['output'];
  kind: LayerKind;
  name?: Maybe<Scalars['String']['output']>;
  opacity: Scalars['Float']['output'];
  order: Scalars['Int']['output'];
  /** The path of transformation edges from this layer's source coordinate system to its scene's world system. A layer belongs to exactly one scene, so this is the one 'to world' question with a single right answer -- the path uses the layer's dataset facts plus the world's registrations, which are the same for every scene over that space. Null when the layer is unregistered or has no source system; empty when the source already is the world system. Every step is here in full, with its own validity, invariance and provenance, which is what to ask for when you care *how* the data got placed; `asAffine` is the same path composed, for when you only need the map */
  pathToWorld?: Maybe<Array<PlacementStep>>;
  /** Whether this layer has a place in its scene's world, and if not, why not. A null `pathToWorld` means three different things -- nobody has registered this data yet, its geometry did not survive the operation that produced it and it can never be placed, or it is registered per index and you have not said which index -- and a client should not have to guess which. UNREGISTERED is a gap to close; UNMAPPABLE is a fact to badge; CONDITIONAL is a placement to ask again for with `at`. Pass the same `at` you would pass `pathToWorld` to be told about that coordinate. Derived, never stored */
  placement: PlacementState;
  /** Which geometric properties survive the whole walk from this layer's data to its scene's world: the weakest edge on its path. ISOMETRY means a distance measured in the data IS that distance in world; SIMILARITY means shapes and angles transfer and every length needs one common factor; AFFINE means only parallelism and area ratios do, so an angle or a distance read in the data means nothing in world; DIFFEOMORPHIC means nothing metric survives anywhere; NONE means there is no path at all. This is what says whether a scalar length in scene units (`pointSize`, `lineWidth`, a stroke width, a camera zoom) is well defined for this layer: it is, from SIMILARITY up. A layer placed per index reports one of its scoped routes rather than NONE; pass `at` for that coordinate's exact answer. Derived, never stored -- and distinct from a single edge's `invariance`, this being the minimum over the whole path. `placement` says which of the reasons a NONE layer has */
  placementInvariance: TransformInvariance;
  /** How much this layer's placement is actually known: the weakest edge on its path to world. UNKNOWN while the path rests on an edge a client marked as guessed, and when there is no path at all; MANUAL once someone authored the registration; VALIDATED once it was checked, and by construction when the path is empty -- data in its own space is placed exactly. A layer placed per index reports one of its scoped routes rather than UNKNOWN; pass `at` for that coordinate's exact answer. Derived, never stored -- and distinct from a single edge's `validity`: this is the minimum over the whole path */
  placementValidity: PlacementValidity;
  scene: Scene;
  visible: Scalars['Boolean']['output'];
};


