export type LayerFilter = {
  AND?: InputMaybe<LayerFilter>;
  DISTINCT?: InputMaybe<Scalars['Boolean']['input']>;
  NOT?: InputMaybe<LayerFilter>;
  OR?: InputMaybe<LayerFilter>;
  blending?: InputMaybe<BlendingChoices>;
  id?: InputMaybe<Scalars['ID']['input']>;
  /** Filter by list of IDs */
  ids?: InputMaybe<Array<Scalars['ID']['input']>>;
  kind?: InputMaybe<LayerKindChoices>;
  /** Filter image layers by the lens they render */
  lens?: InputMaybe<Scalars['ID']['input']>;
  /** Filter by the scene this layer is placed in */
  scene?: InputMaybe<Scalars['ID']['input']>;
};

/** The kind of a layer, discriminating which data source it renders and which rendering settings apply. */
export enum LayerKind {
  /** An annotation layer rendering the drawn vector geometry (polygons, boxes, ellipses, lines, paths) of an annotation collection. */
  Annotation = 'ANNOTATION',
  /** The general image layer: array (lens) data rendered through a composable render graph. The kind for a layer that actually composites -- several channels blended together, a hand-authored transfer curve, an inverted mapping, per-channel opacity. When the recipe's shape is fixed, one of INTENSITY, RGB or PHASOR says so directly and carries its settings as fields. */
  Image = 'IMAGE',
  /** One channel of a lens through one colormap -- or one solid tint -- with contrast limits and gamma, optionally projected over z. The fluorescence workhorse. Its settings are fields rather than a render graph because there is nothing here to composite: the graph form of this was a blend node with a single child, and additively blending one thing is that thing. */
  Intensity = 'INTENSITY',
  /** A label layer rendering array (lens) data whose values are discrete object ids -- a segmentation or instance map. It shares the image layer's source but none of its render settings: contrast limits, gamma, colormaps and intensity projections are all meaningless over ids, and what it carries instead is an id-to-color hashing, a transparent background id, contour-or-fill, a selection, and an optional `colorBy` dereferencing the FIELD edge that keys the mask's pixels to a table of objects. */
  Label = 'LABEL',
  /** A mesh layer rendering a 3D surface reconstruction. */
  Mesh = 'MESH',
  /** A network layer rendering a node/edge graph from a konnektion collection -- a traced arbor, a vessel tree, a connectome. Distinct from TRACK, which draws trajectories from a table and can only express a path: a network is a graph, so it carries branch points, and a dividing cell or a dendrite is not a trajectory. Its segments are drawn as camera-facing quads, which is also why `lineWidth` and `nodeSizeColumn` mean something only from SIMILARITY up. */
  Network = 'NETWORK',
  /** One axis of a lens -- MICROTIME or SPECTRUM -- reduced per pixel to a phasor and coloured by it: a lifetime, or a spectral centre of mass. Its recipe lives in `phasorRender`, as a label layer's lives in `labelRender`, because a phasor's transfer maps a (g, s) pair plus a photon count rather than a sampled scalar. A phasor may still appear as a node inside an IMAGE layer's graph, which is what composites one with an ordinary channel. */
  Phasor = 'PHASOR',
  /** A point layer rendering a point cloud (e.g. SMLM localisations, centroids) from columns of a table. */
  Point = 'POINT',
  /** Three channels of a lens as the red, green and blue components of one picture -- a photograph, a brightfield slide -- sharing one pair of contrast limits. Its own kind rather than a three-child blend because the two are indistinguishable as graphs, and a three-marker fluorescence acquisition coloured red/green/blue is by far the commoner reading of that shape. Never inferred from that shape, for the same reason: a bootstrapped scene reaches this kind only on something ingest recorded -- channels *named* red, green and blue, or arrays read out of a PNG -- or on a caller saying so. Keeping the three together is the point: they are components of one picture, not three signals to hide and reorder separately. */
  Rgb = 'RGB',
  /** A track layer rendering trajectories from columns of a table, grouped by a track id. */
  Track = 'TRACK',
  /** A vector layer rendering a vector-valued lens -- an optical flow, a deformation field, an orientation map -- as glyphs sampled from the grid. The sixth lens-backed kind, and the value axis is what makes it one: the lens carries a DISPLACEMENT axis whose positions are the components of a per-point offset, so the axis is read as geometry rather than composited as channels. Which axis that is is derived (`renderAxes.vector`), never stored; what the layer carries is view state -- a glyph style, a sampling stride, a magnitude scale and a magnitude colormap window. `glyphScale` maps a magnitude in the component axis's unit to a drawn length in scene units, so like `pointSize` it means something only from SIMILARITY up. */
  Vector = 'VECTOR'
}

export enum LayerKindChoices {
  Annotation = 'ANNOTATION',
  Image = 'IMAGE',
  Intensity = 'INTENSITY',
  Label = 'LABEL',
  Mesh = 'MESH',
  Network = 'NETWORK',
  Phasor = 'PHASOR',
  Point = 'POINT',
  Rgb = 'RGB',
  Track = 'TRACK',
  Vector = 'VECTOR'
}

/** A node in a layer's internal render graph. A 'channel' node carries an intensity source and transfer function; a 'phasor' node reduces an axis to a phasor and colors the pixel by it; a 'blend' node composites its children; a 'projection' node projects theirs over z. */
export type LayerNodeInput = {
  blending?: InputMaybe<Blending>;
  children?: InputMaybe<Array<LayerNodeInput>>;
  harmonic?: InputMaybe<Scalars['Int']['input']>;
  intensityAxis?: InputMaybe<Scalars['String']['input']>;
  intensityIndex?: InputMaybe<Scalars['Int']['input']>;
  kind: Scalars['String']['input'];
  label?: InputMaybe<Scalars['String']['input']>;
  mode?: InputMaybe<ProjectionMode>;
  phasorAxis?: InputMaybe<Scalars['String']['input']>;
  phasorTransfer?: InputMaybe<PhasorTransferInput>;
  transfer?: InputMaybe<TransferFunctionInput>;
  visible?: InputMaybe<Scalars['Boolean']['input']>;
};

export type LayerOrder =
  { id: Ordering; };

/** The composable render recipe inside a single layer, rooted at a blend node */
export type LayerRenderGraph = {
  __typename?: 'LayerRenderGraph';
  root: BlendNode;
};

/** The composable render recipe inside a single layer, rooted at a blend node */
export type LayerRenderGraphInput = {
  root: LayerNodeInput;
};

/** A node in a layer's internal render graph */
export type LayerRenderNode = {
  /** The discriminator of the node: 'channel', 'phasor', 'blend' or 'projection' */
  kind: Scalars['String']['output'];
  /** An optional human-readable label for the node */
  label?: Maybe<Scalars['String']['output']>;
};

/** A Lens is a way of looking at a dataset: a dimensional selection (slices) over a dataset that defines a view of its data */
export type Lens = {
  __typename?: 'Lens';
  activeAnchors: Array<CoordinateAnchor>;
  /** The lens' axis names, in array order. A selection never drops or reorders an axis */
  axisNames: Array<Scalars['String']['output']>;
  /** Every column a label layer over this lens can be coloured or filtered by, with the control each one's role admits -- the same set `createLabelLayer(render: {colorBys: ...})` accepts. The nested form of the `labelColorByOptions` root query, which is where the search, narrowing and paging live; this one hands back the whole list. It walks the coordinate graph once per lens, so read it on a lens, not across a page of them */
  colorByOptions: Array<ColorByOption>;
  /** The coordinate system the lens' selection is expressed in. A sliced lens owns one (the space its slices cut out, with the derived edge recording the shift); an unsliced lens selects everything, so this resolves to the dataset's INTRINSIC system */
  coordinateSystem?: Maybe<CoordinateSystem>;
  dataset: ArrayDataset;
  /** The datasets computed from this lens' selection: the direct other end of `derivedFrom`, which names a *lens* as a parent rather than a dataset. An unsliced lens reports what was derived from the whole intrinsic grid -- its space is that grid, so it can say nothing narrower. Like the forward field this reports every child, whether or not this lens is its primary parent and whether or not its geometry survived */
  derivedDatasets: Array<ArrayDataset>;
  id: Scalars['ID']['output'];
  /** The most recent picture of this lens' dataset's `defaultScene` -- the tile to put on this lens. The same picture the dataset itself reports: the nomination is a fact about the dataset, so every lens over one dataset answers alike. Null when the dataset nominates no scene */
  latestSnapshot?: Maybe<SceneSnapshot>;
  /** Everything needed to reduce one axis of this lens to a phasor: the bin count and width, the period the transform runs over, the laser rate, the instrument-response correction and the persisted distribution. Null when the lens has no MICROTIME or SPECTRUM axis. Derived -- none of it is stored on the lens, and a phasor render node references it rather than copying it, so two layers over one dataset cannot disagree about the instrument */
  phasor?: Maybe<PhasorContext>;
  /** Which axis of the data source maps to screen x, y, z, time and intensity. Derived from the axis types: spatial axes are in array order, so the last is x */
  renderAxes: RenderAxes;
  /** The shape this lens' slices cut out of its dataset */
  shape: Array<Scalars['Int']['output']>;
  slices: Array<Slice>;
  /** The edge from this lens' space back into its dataset's intrinsic pixel space. A crop is a translation of the slice starts; a stepped lens also rescales. Without this edge an ROI drawn on a cropped lens has no defined path back to its dataset. Null for an unsliced lens: its space IS the intrinsic space, and there is no shift to record */
  toParent?: Maybe<Transformation>;
};


/** A Lens is a way of looking at a dataset: a dimensional selection (slices) over a dataset that defines a view of its data */
export type LensColorByOptionsArgs = {
  maxJoinDepth?: Scalars['Int']['input'];
};


/** A Lens is a way of looking at a dataset: a dimensional selection (slices) over a dataset that defines a view of its data */
export type LensPhasorArgs = {
  axis?: InputMaybe<Scalars['String']['input']>;
  harmonic?: Scalars['Int']['input'];
};

/** The fields a LENS derivation reads. Published for codegen; the wire type is the flat DerivedFromInput */
export type LensDerivedFromInput = {
  kind?: DerivationSourceKind;
  lens: Scalars['ID']['input'];
  transform?: InputMaybe<TransformInput>;
  valueRelation?: InputMaybe<ValueRelation>;
};

/** Thin lens */
export type LensElement = OpticalElement & {
  __typename?: 'LensElement';
  focalLength: Scalars['Length']['output'];
  id: Scalars['ID']['output'];
  /** Element kind */
  kind: ElementKind;
  /** Element label */
  label: Scalars['String']['output'];
  manufacturer?: Maybe<Scalars['String']['output']>;
  model?: Maybe<Scalars['String']['output']>;
  /** List of ports on the element */
  ports: Array<LightPort>;
  /** 3D pose of the element */
  pose?: Maybe<Pose3D>;
  serialNumber?: Maybe<Scalars['String']['output']>;
};

/** The fields a LENS element reads. Published for codegen; the wire type is the flat OpticalElementInput */
export type LensElementInput = {
  focalLength?: InputMaybe<Scalars['Length']['input']>;
  id?: InputMaybe<Scalars['ID']['input']>;
  kind?: ElementKind;
  label: Scalars['String']['input'];
  manufacturer?: InputMaybe<Scalars['String']['input']>;
  model?: InputMaybe<Scalars['String']['input']>;
  ports?: InputMaybe<Array<LightPortInput>>;
  pose?: InputMaybe<Pose3DInput>;
  serialNumber?: InputMaybe<Scalars['String']['input']>;
};

export type LensFilter = {
  AND?: InputMaybe<LensFilter>;
  DISTINCT?: InputMaybe<Scalars['Boolean']['input']>;
  NOT?: InputMaybe<LensFilter>;
  OR?: InputMaybe<LensFilter>;
  /** Filter by the dataset this lens looks at */
  dataset?: InputMaybe<Scalars['ID']['input']>;
  id?: InputMaybe<Scalars['ID']['input']>;
  /** Filter by list of IDs */
  ids?: InputMaybe<Array<Scalars['ID']['input']>>;
  /** Filter to lenses placeable into a coordinate system: those whose space reaches it across steps that compose into one affine map, walking the transformation edges. Takes a *space*, not a scene -- pass `scene.worldCoordinateSystem.id` to ask it of a scene. `derivedOnly` and `asLayer` narrow the answer for a particular picker; with neither, this is the whole set layer creation would accept */
  placeableIn?: InputMaybe<LensPlaceableFilter>;
};

/** The kind of layer a lens could source, for narrowing a picker: the members of `LayerKind` that draw array data. Input-only, and deliberately not `LayerKind` itself -- an annotation, point, track or mesh layer sources from a collection or a table, never from a lens, so four of that enum's members could only ever answer 'no'. */
export enum LensLayerKind {
  /** Drawable as a general image layer -- which is every lens with an x and a y axis of more than one pixel. It is the renderability gate alone, and deliberately *not* the complement of the others: a mask drawn through a render graph is a legitimate thing to want, and `createLayer` does not refuse one. */
  Image = 'IMAGE',
  /** Drawable as an intensity layer: renderable, which is the whole condition. Every lens an image layer can draw, one channel of it can also be drawn on its own. */
  Intensity = 'INTENSITY',
  /** Drawable as a label layer: renderable, and derived by an edge declaring CATEGORIZED -- the values became object ids. The same signal `createSceneFromCoordinateSystem` infers a label layer from, asked of a candidate instead of a source, so a picker and a bootstrapped scene cannot disagree about what a label is. */
  Label = 'LABEL',
  /** Drawable as a phasor layer: renderable, and carrying a MICROTIME or SPECTRUM axis -- the continuous ones a phasor transform means anything over. */
  Phasor = 'PHASOR',
  /** Drawable as an RGB layer: renderable, and carrying a channel axis with at least three positions. Structural capacity only -- whether those three channels *are* red, green and blue is a fact about the acquisition, which a shape cannot carry. `createSceneFromCoordinateSystem` answers it from what ingest recorded (channel labels, a photographic source file) and falls back to one layer per channel; this filter answers the narrower structural question and never guesses. */
  Rgb = 'RGB',
  /** Drawable as a vector layer: renderable, and carrying a DISPLACEMENT value axis -- the values are components of a per-point offset. The same signal `createSceneFromCoordinateSystem` infers a vector layer from, asked of a candidate instead of a source, for LABEL's stated reason. */
  Vector = 'VECTOR'
}

export type LensOrder =
  { id: Ordering; };

/** What a lens picker is asking for: a destination space, and optionally which sort of candidate. Structured rather than a bare space id because `derivedOnly` and `asLayer` are qualifications *of* the placeability question -- a lens is not derived or label-shaped in the abstract, it is those things on the way into a particular space */
export type LensPlaceableFilter = {
  /** Keep only the lenses that could source a layer of this kind. Every member requires the lens to be drawable at all -- an x and a y axis of more than one pixel, the same gate layer creation applies. Three ask something further: `LABEL` a primary derivation declaring CATEGORIZED, `RGB` a channel axis with at least three positions, and `PHASOR` a MICROTIME or SPECTRUM axis. `RGB` is capacity only -- whether those three channels *are* red, green and blue is not a question any axis can answer, which is why RGB is never inferred. Note that *omitting* this applies no renderability gate, so `IMAGE` is a real narrowing rather than a no-op: the unqualified filter answers what is placeable, which is a spatial question, not what is drawable */
  asLayer?: InputMaybe<LensLayerKind>;
  /** Keep only the lenses that *needed* a lineage tree to get here: the segmentations, deconvolutions and projections placed by an ancestor's registration. What the space registers directly is dropped, even when it is itself a derived dataset -- it does not need its lineage to be placeable. A narrowing of the candidate list and nothing more: every lens it keeps is one `createLayer` accepts, and every lens it drops is too */
  derivedOnly?: InputMaybe<Scalars['Boolean']['input']>;
  /** The space to be placed into. A *space*, not a scene: every scene over one world offers the same candidates, so a scene-shaped argument would ask for more than the answer depends on. Pass `scene.worldCoordinateSystem.id` to ask it of a scene */
  space: Scalars['ID']['input'];
};

/** The placement of one pyramid level in a layer's scene: the level and its path to the world system */
export type LevelPlacement = {
  __typename?: 'LevelPlacement';
  /** The pyramid level being placed */
  dataArray: DataArray;
  /** The path from this level's voxel grid to the scene's world system, or null when the dataset is not registered into the scene */
  path?: Maybe<Array<PlacementStep>>;
};

