/** One optical element, as a discriminated union: `kind` selects a member, and only that member's fields are read -- any other supplied field is rejected, never carried. The member inputs annotated `@unionElementOf(union: "OpticalElementInput")` say which fields each kind reads */
export type OpticalElementInput = {
  /** (DETECTOR) Amplifier gain (dB). */
  amplifierGainDb?: InputMaybe<Scalars['Float']['input']>;
  /** (MIRROR, POLARIZER, WAVEPLATE) The relevant angle, in degrees. */
  angleDeg?: InputMaybe<Scalars['Float']['input']>;
  /** (MIRROR, BEAM_SPLITTER) Maximum wavelength of the coating band (e.g. '700 nm'). */
  bandMax?: InputMaybe<Scalars['Length']['input']>;
  /** (MIRROR, BEAM_SPLITTER) Minimum wavelength of the coating band (e.g. '400 nm'). */
  bandMin?: InputMaybe<Scalars['Length']['input']>;
  /** (OBJECTIVE) Brand of the objective. */
  brand?: InputMaybe<Scalars['String']['input']>;
  /** (LASER, LAMP, OTHER_SOURCE) Propagation channel of the output. */
  channel?: InputMaybe<ChannelKind>;
  /** (SAMPLE, OTHER, FILTER) A free-form description of the element. */
  description?: InputMaybe<Scalars['String']['input']>;
  /** (WAVEPLATE) The wavelength the retardance is specified at (e.g. '532 nm'). */
  designWavelength?: InputMaybe<Scalars['Length']['input']>;
  /** (PINHOLE, APERTURE) Diameter of the hole (e.g. '50 µm'). */
  diameter?: InputMaybe<Scalars['Length']['input']>;
  /** (POLARIZER) Ratio of transmitted to blocked polarization. */
  extinctionRatio?: InputMaybe<Scalars['Float']['input']>;
  /** (FILTER) The kind of filter, e.g. 'Dichroic', 'BandPass'. */
  filterKind?: InputMaybe<FilterKind>;
  /** (LENS) Focal length (e.g. '200 mm'). */
  focalLength?: InputMaybe<Scalars['Length']['input']>;
  /** (DETECTOR, SHUTTER) Overall gain, unitless -- the drive gain for an AOTF or EOM used as a gate. */
  gain?: InputMaybe<Scalars['Float']['input']>;
  /** (LASER) Has a Pockels cell. */
  hasPockelsCell?: InputMaybe<Scalars['Boolean']['input']>;
  /** (LASER) Has a Q-switch. */
  hasQSwitch?: InputMaybe<Scalars['Boolean']['input']>;
  /** Optional UUID of the element (provide for updates). */
  id?: InputMaybe<Scalars['ID']['input']>;
  /** (OBJECTIVE) Immersion medium, e.g. 'Oil', 'Water'. */
  immersionMedium?: InputMaybe<ObjectiveImmersion>;
  /** (OBJECTIVE) Has an iris (aperture stop). */
  iris?: InputMaybe<Scalars['Boolean']['input']>;
  /** (SHUTTER) Whether the shutter was open at this coordinate. */
  isOpen?: InputMaybe<Scalars['Boolean']['input']>;
  /** Kind of optical element. It fixes which of the fields below are read; any field outside the chosen kind's member is rejected. */
  kind: ElementKind;
  /** Human-readable label for the optical element. */
  label: Scalars['String']['input'];
  /** (LAMP, OTHER_SOURCE) Lamp type, e.g. 'LED', 'Halogen', 'Xenon', 'Mercury'. */
  lampType?: InputMaybe<Scalars['String']['input']>;
  /** (LASER) Laser medium, e.g. 'Ti:Sapphire', 'Nd:YAG'. */
  laserMedium?: InputMaybe<Scalars['String']['input']>;
  /** (OBJECTIVE) Magnification factor, e.g. 20 for 20x. */
  magnification?: InputMaybe<Scalars['Float']['input']>;
  /** Manufacturer of the optical element. */
  manufacturer?: InputMaybe<Scalars['String']['input']>;
  /** Model name or number of the optical element. */
  model?: InputMaybe<Scalars['String']['input']>;
  /** (DETECTOR) Noise-equivalent power density (W/√Hz). */
  nepdWPerSqrtHz?: InputMaybe<Scalars['Float']['input']>;
  /** (LASER) Nominal output wavelength (e.g. '488 nm'). */
  nominalWavelength?: InputMaybe<Scalars['Length']['input']>;
  /** (OBJECTIVE) Numerical aperture. */
  numericalAperture?: InputMaybe<Scalars['Float']['input']>;
  /** (CCD) Pixel size (e.g. '6.5 µm'). */
  pixelSize?: InputMaybe<Scalars['Length']['input']>;
  /** List of optical ports belonging to the element. */
  ports?: InputMaybe<Array<LightPortInput>>;
  /** Optional spatial pose of the element. */
  pose?: InputMaybe<Pose3DInput>;
  /** (LASER) Output power (e.g. '20 mW'). */
  power?: InputMaybe<Scalars['Power']['input']>;
  /** (LASER) Pulse type, e.g. 'CW', 'ModeLocked'. */
  pulseKind?: InputMaybe<PulseKind>;
  /** (BEAM_SPLITTER) Reflectance fraction (0-1). */
  rFraction?: InputMaybe<Scalars['Float']['input']>;
  /** (LASER) Repetition rate (e.g. '80 MHz'). */
  repetitionRate?: InputMaybe<Scalars['Frequency']['input']>;
  /** (CCD) Sensor resolution (width, height) in pixels. */
  resolution?: InputMaybe<Array<Scalars['Int']['input']>>;
  /** (WAVEPLATE) Retardance in waves, e.g. 0.5 for a half-wave plate. */
  retardance?: InputMaybe<Scalars['Float']['input']>;
  /** Serial number of the optical element. */
  serialNumber?: InputMaybe<Scalars['String']['input']>;
  /** (SHUTTER) How it switches, e.g. 'mechanical', 'AOTF', 'EOM'. */
  shutterType?: InputMaybe<Scalars['String']['input']>;
  /** (BEAM_SPLITTER) Transmittance fraction (0-1). */
  tFraction?: InputMaybe<Scalars['Float']['input']>;
  /** (FILTER) Peak transmittance (0-1). */
  transmittance?: InputMaybe<Scalars['Float']['input']>;
  /** (OBJECTIVE) Working distance (e.g. '2 mm'). */
  workingDistance?: InputMaybe<Scalars['Length']['input']>;
};

