/** A per-axis multiplication, with one entry per input axis */
export type ScaleTransformationProvenanceEntriesArgs = {
  pagination?: InputMaybe<OffsetPaginationInput>;
};

/** A composition of layers over a shared world coordinate system. The scene carries no units of its own -- they are per-axis, on the axes of its world system */
export type Scene = {
  __typename?: 'Scene';
  /** The named camera tours through this composition */
  animations: Array<Animation>;
  /** The annotation collection minted for this scene as its default drawing surface, or null before the first annotation is drawn on it. Bookkeeping, not placement: what places the collection is its registration edge into this scene's world */
  annotationCollection?: Maybe<AnnotationCollection>;
  /** The viewer background, as RGBA. Null lets the viewer use its own */
  backgroundColor?: Maybe<Array<Scalars['Float']['output']>>;
  /** The datasets that nominate this scene as the one to open for them, and take their thumbnail from it. Several may: a scene staging a plate is a reasonable landing place for every dataset in it. Not the datasets this scene *shows* -- for that, ask each dataset's `scenes`, which the coordinate graph derives */
  defaultFor: Array<ArrayDataset>;
  id: Scalars['ID']['output'];
  /** The most recent picture of this composition -- the tile to put on the scene. Null until something snapshots it */
  latestSnapshot?: Maybe<SceneSnapshot>;
  /** The layers placed in this scene (a heterogeneous list of layer kinds) */
  layers: Array<Layer>;
  name: Scalars['String']['output'];
  /** How a viewer should open this scene: flat, volumetric, or its own choice. A preference, not a constraint -- nothing server-side reads it, and a viewer that cannot render volumes is not wrong to show the slice view */
  preferredView: PreferredView;
  /** The pre-rendered pictures of this composition, for previewing it without compositing the layers */
  snapshots: Array<SceneSnapshot>;
  /** The shared space this scene composes its layers over. Never owned by the scene: many scenes can share it, it outlives each of them, and deleting a scene never deletes it */
  worldCoordinateSystem: CoordinateSystem;
};


/** A composition of layers over a shared world coordinate system. The scene carries no units of its own -- they are per-axis, on the axes of its world system */
export type SceneAnimationsArgs = {
  filters?: InputMaybe<AnimationFilter>;
  ordering?: Array<AnimationOrder>;
  pagination?: InputMaybe<OffsetPaginationInput>;
};


/** A composition of layers over a shared world coordinate system. The scene carries no units of its own -- they are per-axis, on the axes of its world system */
