export const GetArrayDatasetDerivedDocument = gql`
    query GetArrayDatasetDerived($id: ID!) {
  arrayDataset(id: $id) {
    id
    intrinsicSystem {
      id
      name
    }
    provenanceEntries {
      ...ProvenanceEntry
    }
    sourceFiles {
      ...FileLink
    }
    exports {
      ...FileLink
    }
    derivedFrom {
      id
      kind
      valueRelation
      output {
        id
        name
        residents {
          __typename
          ... on ArrayDataset {
            id
            name
          }
          ... on Lens {
            id
            dataset {
              id
              name
            }
          }
        }
      }
      ... on UnmappableTransformation {
        reason
      }
    }
    derivedDatasets {
      ...ListArrayDataset
      derivedFrom {
        id
        kind
        valueRelation
        output {
          id
          name
        }
        ... on UnmappableTransformation {
          reason
        }
      }
    }
  }
  lenses(filters: {dataset: $id}) {
    id
    axisNames
    shape
    slices {
      ...DimSlice
    }
    coordinateSystem {
      id
      name
    }
  }
}
    ${ProvenanceEntryFragmentDoc}
${FileLinkFragmentDoc}
${ListArrayDatasetFragmentDoc}
${DimSliceFragmentDoc}`;
